const checks=[],shots=[],errors=[];let mini,backup;
async function evaluate(fn,arg=null){const call=new Function('return function englishIndividual98(){const payload='+JSON.stringify(arg)+';getApp().globalData.englishIndividual98={pending:true};Promise.resolve().then(()=>('+fn.toString()+')(payload)).then(value=>getApp().globalData.englishIndividual98={pending:false,value},error=>getApp().globalData.englishIndividual98={pending:false,error:String(error.message||error.errMsg||error)});return true;}')();await mini.evaluate(call);const end=Date.now()+90000;while(Date.now()<end){const r=await mini.evaluate(function(){return getApp().globalData.englishIndividual98;});if(r&&!r.pending){if(r.error)throw Error(r.error);return r.value}await new Promise(r=>setTimeout(r,100))}throw Error('Native controller task timed out')}
const action=(name,value='')=>evaluate(async p=>{await getApp().globalData.application.action(p.name,p.value);return true},{name:'studio-'+name,value});
const field=(name,value)=>evaluate(p=>{getApp().globalData.application.setField(p.name,p.value);return true},{name,value});
const view=()=>evaluate(()=>{const v=getApp().globalData.application.render().teaching;return{step:v.progress.step,id:v.lesson.id,workshop:v.workshop,correct:v.correct,answer:v.answer,before:v.progress.before,after:v.progress.after}});
async function mounted(){let lastPath='';for(let n=0;n<100;n++){const page=await mini.currentPage();lastPath=page.path;if(lastPath.replace(/^\//,'')==='pages/lesson/index'){const shell=await page.$('app-shell'),studio=shell&&await shell.$('lesson-studio');if(studio){const v=await studio.data('view');if(v?.lesson.id===id)return{page,shell,studio}}}await new Promise(resolve=>setTimeout(resolve,150))}throw Error('Budget lesson native route/component not mounted; last path: '+lastPath)}

async function shot(name,focusSelector){await mini.pageScrollTo(0);const {page,studio}=await mounted();await page.waitFor(150);
 for(const list of await studio.$$('.reading-evidence-list')){const width=(await list.size()).width;for(const card of await list.$$('.reading-evidence'))assert((await card.size()).width>=width-2,'Native evidence cards must fill their list')}
 const selector=focusSelector||(/reduction-/.test(name)?'.reading-calculation':/location-/.test(name)?'.location-map':/pacing-(off|on)-/.test(name)?'.pacing-diagram':/factor|household|cooperation|serving|pacing|fairplay|festival|claims|credit|contact|verify|scope|headline|reports|plantreport|testrecord|trailplan|flowplan|watchplan|recordplan|cupreport|cleanup|waiting|sitebrief|modelclaims|observation/.test(name)?'.source-settings':/notebook|ruler|photo|opening|lake|orange|lantern|weaving|occupied|birdwatch|clearway|balls/.test(name)?'.event-art-wrap':/yuan|balance|arrival|task-[12]-/.test(name)?'.reading-calculation':/gap|task-3-/.test(name)?'.cloze-context':/order|task-4-/.test(name)?'.source-order':/task-[567]-/.test(name)?'.reading-evidence-list':/application|transfer-reference/.test(name)?'.studio-reading':null);
 if(selector){const target=await studio.$(selector);if(target){const offset=await target.offset();await mini.pageScrollTo(Math.max(0,offset.top-100));await page.waitFor(180)}}
 const file=name+'.png';await mini.screenshot({path:path.join(out,file)});shots.push(file)}

async function tap(selector){const {studio,page}=await mounted();const el=await studio.$(selector);assert(el,'Missing native control '+selector);await mini.pageScrollTo(0);await page.waitFor(150);await el.trigger('tap');await page.waitFor(120)}
async function nativeInput(value){const {studio,page}=await mounted();const el=await studio.$('input[data-name="studioWorkshopInput"]');assert(el,'Native calculation input must render');await mini.pageScrollTo(0);await page.waitFor(150);await el.input(value);await page.waitFor(150);assert.equal((await view()).workshop.input,value)}

async function nativeField(name,value){const {studio,page}=await mounted();const el=await studio.$('textarea[data-name="'+name+'"]')||await studio.$('input[data-name="'+name+'"]');assert(el,'Native field must render: '+name);await mini.pageScrollTo(0);await page.waitFor(150);await el.input(value);await page.waitFor(150);assert.equal(name==='studioWorkshopOwn'?(await view()).workshop.own:name==='studioBefore'?(await view()).before:name==='studioAfter'?(await view()).after:(await view()).answer,value)}
